  "Search apps…": "Tìm ứng dụng…",
  "Search contacts": "Tìm trong danh bạ",
  "Sections": "Mục",
  "Seek": "Tua",
  "Send (carrier rates apply)": "Gửi (áp dụng cước nhà mạng)",
  "Send clipboard to phone": "Gửi bảng nhớ tạm sang điện thoại",
